#!/usr/bin/env python3
"""Render the reviewed discoveries collection. No network, credentials or model calls."""
import json,re,sys
from pathlib import Path
from html import escape as esc
from datetime import date
from urllib.parse import urlparse
ROOT=Path(__file__).resolve().parent

def build():
 data=json.loads((ROOT/'stories.json').read_text());stories=data['stories'];ids={s['id'] for s in stories}
 assert len(ids)==len(stories),'Duplicate discovery IDs'
 articles=[]
 for n,s in enumerate(stories):
  for key in ('title','takeaway','context','coveredOn','category','status','evidenceKind','sources'):assert s.get(key),f'Missing {key}: {s["id"]}'
  for url in s['sources']:assert urlparse(url).scheme=='https' and urlparse(url).hostname, 'Only public HTTPS sources allowed'
  assert re.fullmatch(r'[a-z0-9-]+',s['id'])
  date.fromisoformat(s['coveredOn'])
  image=''
  if s.get('illustration'):
   path='illustrations/'+s['illustration']+'.svg';assert (ROOT/path).is_file()
   image=f'<figure class="story-figure"><img src="{path}" width="800" height="440" loading="lazy" decoding="async" alt="{esc({"symmetry":"A patterned hexagon before and after a turn illustrates symmetry.","research-loop":"A loop: ask a question, run a test, check the answer, then change the plan.","molecular-grip":"Two puzzle-like shapes illustrate a protein grip fitting its target.","cell-switch":"A shorter internal switch leaves room in an engineered immune cell’s genetic instructions.","allergy-latch":"A helper shape illustrates detaching an allergy trigger from an immune cell.","waves":"An illustrative wave concentrates into a brief peak.","branching":"A tree of choices illustrates how a search grows as more decisions are added."}[s["illustration"]])}"><figcaption>Concept illustration · not experimental data</figcaption></figure>'
  # Main article is a small, clear explanation. The source-channel account retains
  # the specific AI/human contribution, numerical results and evidence limitations.
  paragraphs=''.join(f'<p>{esc(p.strip())}</p>' for p in s['context'].split('\n\n') if p.strip())
  links=''.join(f'<a href="{esc(u,quote=True)}" target="_blank" rel="noopener noreferrer">{("Read the original article" if i==0 else "Supporting source")} <span aria-hidden="true">↗</span><span class="source-host">{esc(urlparse(u).hostname.removeprefix("www."))}</span></a>' for i,u in enumerate(s['sources']))
  related=''.join(f'<a href="#{esc(r)}">Related report or correction →</a>' for r in s.get('related',[]) if r in ids)
  articles.append(f'''<article class="discovery-story" id="{s['id']}" data-topic="{esc(s['category'],quote=True)}" data-kind="{s['evidenceKind']}"><div class="story-top"><span class="topic-label">{esc(s['category'])}</span><time datetime="{s['coveredOn']}">Covered {date.fromisoformat(s['coveredOn']).strftime('%b %d, %Y')}</time></div>{image}<div class="story-content"><span class="evidence-tag {s['evidenceKind']}">{esc(s['status'])}</span><h3><a href="#{s['id']}">{esc(s['title'])}</a></h3><p class="takeaway">{esc(s['takeaway'])}</p>{f'<div class="later-update">{related}</div>' if related else ''}<details class="story-detail"><summary>What happened, who did what &amp; the limits</summary><div class="report-context">{paragraphs}</div><p class="context-note">This is the source-channel account at the time it was shared. An early report is not a guarantee the claim will stand.</p></details><div class="story-sources">{links}</div></div></article>''')
 html='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<script>(function(){try{if(localStorage.getItem('theme')==='light')document.documentElement.setAttribute('data-theme','light');}catch(e){}})();</script>
<title>AI Discoveries, Explained — Jez237</title>
<meta name="description" content="AI science news without the science degree. Everyday explanations, original illustrations and direct sources for discoveries, experiments, proof claims and corrections.">
<meta name="robots" content="index, follow"><link rel="canonical" href="https://jez237.com/ai-news/discoveries/">
<meta property="og:title" content="AI Discoveries, Explained — Jez237"><meta property="og:description" content="Big ideas. Everyday explanations. See what AI actually contributed—and what still needs checking."><meta property="og:type" content="website"><meta property="og:url" content="https://jez237.com/ai-news/discoveries/">
<link rel="stylesheet" href="../../assets/styles.css"><link rel="stylesheet" href="../../assets/design.css"><link rel="stylesheet" href="../../assets/site-enhance.css"><link rel="stylesheet" href="../../assets/workbench-theme.css"><link rel="stylesheet" href="../../assets/ai-news.css?v=20260710-tools-images-v2"><link rel="stylesheet" href="discoveries.css?v=20261031">
</head><body class="ai-news-page discoveries-page"><a class="skip-content" href="#stories">Skip to discoveries</a><header id="site-nav"></header>
<main class="container"><nav class="discovery-breadcrumb" aria-label="Breadcrumb"><a href="../../">Home</a><span aria-hidden="true">/</span><a href="../">AI News</a><span aria-hidden="true">/</span><span aria-current="page">Discoveries, explained</span></nav>
<section class="discovery-hero" aria-labelledby="page-title"><div class="hero-copy"><p class="kicker"><span class="signal-dot"></span>AI Discovery Watch</p><h1 id="page-title">Big discoveries.<br><em>Human-sized explanations.</em></h1><p class="hero-deck">What did AI actually figure out? Why should you care? And how sure are we? Explore the science—one clear idea at a time.</p><div class="hero-actions"><a class="primary-link" href="#stories">Explore the discoveries <span aria-hidden="true">↓</span></a><a href="#how-to-read">How to read the evidence →</a></div><p class="coverage-line">{{COUNT}} reports &amp; updates · Channel coverage through {{COVERAGE}}</p></div><div class="hero-art"><img src="illustrations/research-loop.svg" width="800" height="440" alt="The research loop: ask a question, run a test, check the answer, and let evidence shape the next test."><div class="hero-art-caption"><span>THE BIG IDEA</span><p>AI can suggest the next question.<br><strong>Evidence still gets the final say.</strong></p></div></div></section>
<section class="featured-lesson" aria-labelledby="spotlight-title"><div><p class="kicker">Start here · Medicine &amp; biology</p><h2 id="spotlight-title">Unhooking an allergy trigger</h2><p>Think of an allergy trigger clipped to an immune cell. Researchers used AI to design tiny helpers that might unclip it. Some worked in laboratory tests.</p><p><strong>The important distinction:</strong> those helpers are starting pieces—not a finished allergy treatment.</p><a href="#{{ALLERGY_ID}}">The full story &amp; original research →</a></div><figure><img src="illustrations/allergy-latch.svg" width="800" height="440" decoding="async" alt="An analogy diagram: a designed helper detaches an allergy trigger from an immune cell."><figcaption>A visual analogy, not a literal molecular diagram.</figcaption></figure></section>
<section class="evidence-guide" id="how-to-read" aria-labelledby="evidence-title"><div class="section-heading"><div><p class="kicker">Curiosity, with the brakes working</p><h2 id="evidence-title">A claim is the beginning. Checking is the journey.</h2></div><button type="button" class="guide-toggle" aria-expanded="false" aria-controls="evidence-notes">A 30-second guide <span aria-hidden="true">+</span></button></div><div id="evidence-notes" hidden><div class="guide-grid"><div><h3>Early result</h3><p>The team has reported something promising. Other groups may not have checked it yet. A preprint is a research paper shared before journal review.</p></div><div><h3>Lab test ≠ treatment</h3><p>A molecule doing a job in a test is an early step. It says nothing by itself about safety or benefit in people.</p></div><div><h3>Computer check ≠ every claim checked</h3><p>A proof checker checks an exact mathematical statement. A separate written explanation can still contain errors or make a different claim.</p></div><div><h3>AI contribution ≠ no humans</h3><p>People often choose the question, build the tools, run experiments and repair arguments. Open each story to see the division of work.</p></div></div><p>Stories are dated by when the channel covered them. The original research may be earlier. Follow-ups and corrections remain visible rather than quietly disappearing.</p></div></section>
<section class="discovery-library" id="stories" aria-labelledby="library-title"><div class="section-heading"><div><p class="kicker">The discovery notebook</p><h2 id="library-title">Explore the ideas</h2></div><p class="library-updated">Edited {{UPDATED}}</p></div><form class="discovery-controls" role="search"><label for="discovery-search">Find an idea<input type="search" id="discovery-search" placeholder="Try allergies, robots, waves or proof…" autocomplete="off"></label><label for="discovery-topic">Explore a subject<select id="discovery-topic"><option value="">All subjects</option>{{TOPICS}}</select></label><label for="discovery-evidence">Kind of report<select id="discovery-evidence"><option value="">All reports</option><option value="correction">Corrections &amp; cautions</option><option value="followup">Follow-ups &amp; checking</option><option value="demo">Research demonstrations</option><option value="lab">Early laboratory results</option><option value="proof">Mathematical proof reports</option><option value="early">Other early research</option></select></label><button id="clear-filters" type="reset">Clear filters</button></form><div class="library-status"><p id="result-count" role="status" aria-live="polite">{{COUNT}} source-linked reports and updates</p><p>No science degree required. Questions welcome.</p></div><p id="empty-results" hidden>No discoveries match that search. Try a broader word or clear the filters.</p><div id="discovery-grid">{{ARTICLES}}</div><div class="load-more-row"><button id="load-more" type="button" hidden>Show more discoveries <span aria-hidden="true">↓</span></button></div><noscript><p>All stories and source links are available below. Search and filters need JavaScript.</p></noscript></section>
<footer class="discovery-footer"><p><strong>Science is a process, not a victory headline.</strong> These explainers cover reports shared by AI Discovery Watch, including experiments, proposed proofs and corrections—not only settled discoveries.</p><p>{{NOTE}}</p><p>Original diagrams illustrate ideas, not measured data.</p><a href="../">← Back to AI News</a></footer></main>
<script src="discoveries.js?v=20261031" defer></script><script src="../../assets/site-enhance.js" defer></script><script src="../../assets/nav.js?v=nav-20260702b" defer></script></body></html>'''
 topics=sorted({s['category'] for s in stories})
 html=html.replace('{{COVERAGE}}',date.fromisoformat(data['coverageEnd']).strftime('%B %d, %Y')).replace('{{UPDATED}}',date.fromisoformat(data['updated']).strftime('%B %d, %Y')).replace('{{COUNT}}',str(len(stories))).replace('{{ALLERGY_ID}}',next(s['id'] for s in stories if s.get('illustration')=='allergy-latch')).replace('{{TOPICS}}',''.join(f'<option>{esc(t)}</option>' for t in topics)).replace('{{ARTICLES}}','\n'.join(articles)).replace('{{NOTE}}',esc(data['editorialNote']))
 (ROOT/'index.html').write_text(html+'\n')
 print(f'Rendered {len(stories)} reviewed explainers; {sum(len(s["sources"]) for s in stories)} source links.')
if __name__=='__main__':build()
